void rotate(vector<int>& a, int k) {
    k = k % a.size();
    reverse(a.begin(), a.end());
    reverse(a.begin(), a.begin()+k);
    reverse(a.begin()+k, a.end());
}

int firstPos(vector<int>& a, int key) {
    int l=0, r=a.size()-1, ans=-1;
    while(l<=r) {
        int mid=l+(r-l)/2;
        if(a[mid]==key) {
            ans=mid;
            l=mid+1;
        } else if(a[mid]<key) l=mid+1;
        else r=mid-1;
    }
    return ans;
}

int* maxElement(vector<int> a) {
    int* p = &a[0];
    for(int i=1;i<a.size();i++)
        if(a[i] > *p) p=&a[i];
    return p;
}

void deleteKey(Node*& head, int key) {
    Node* cur=head;
    while(cur && cur->next) {
        if(cur->next->data==key) {
            Node* t=cur->next;
            cur->next=t->next;
            delete t;
            return;
        }
        cur=cur->next;
    }
}

int apply(stack<int>& st, char op) {
    int b=st.top(); st.pop();
    int a=st.top(); st.pop();
    return a+b;
}

int diameter(Node* root) {
    if(!root) return 0;
    return max(height(root->left)+height(root->right)+1,
        max(diameter(root->left), diameter(root->right)));
}

bool valid(Node* root, int low, int high) {
    if(!root) return true;
    if(root->data <= low || root->data >= high) return false;
    return valid(root->left, low, root->data) &&
           valid(root->right, root->data, high);
}

bool path(Node* u) {
    visited[u]=true;
    for(Node* v : adj[u])
        if(!visited[v] && path(v)) return true;
    return false;
}

